<?php /** @var app\Core\View $this */$company = $this->data['company'];?><?php $this->layout('app'); ?><div class="erp-page-head">    <div>        <h1>Document Numbering</h1>        <nav aria-label="breadcrumb">            <ol class="breadcrumb">                <li class="breadcrumb-item"><a href="<?= $this->url('/') ?>">Home</a></li>                <li class="breadcrumb-item"><a href="<?= $this->url('/settings') ?>">Settings</a></li>                <li class="breadcrumb-item active">Document Numbering</li>            </ol>        </nav>    </div></div><div class="erp-alert erp-alert-info">    <i class="bi bi-info-circle"></i>    <span>Numbering for <b><?= $this->e($company['name'] ?? '') ?></b>. Example formats:        <code>SI-26-000001</code> or with branch codes <code>LHR-SI-26-000001</code>.</span></div><div class="erp-card">    <div class="erp-card-body p-0">        <div class="table-responsive erp-table-wrap">            <table class="table erp-table mb-0">                <thead>                    <tr>                        <th>Document</th>                        <th>Prefix</th>                        <th>Branch code</th>                        <th>Financial year</th>                        <th>Next number</th>                        <th>Last used</th>                        <th>Length</th>                        <th>Status</th>                        <th class="actions-cell">Actions</th>                    </tr>                </thead>                <tbody>                <?php foreach ($this->data['series'] as $s): ?>                    <tr>                        <td>                            <div class="fw-semibold text-capitalize"><?= $this->e(str_replace('_', ' ', $s['document_type'])) ?></div>                            <div class="small text-muted mono"><?= \app\Controllers\NumberingController::previewNumber($s) ?></div>                        </td>                        <td><code><?= $this->e($s['prefix']) ?></code></td>                        <td><?= (int) $s['include_branch_code'] === 1 ? '<span class="badge badge-soft-success">Yes</span>' : '<span class="badge badge-soft-neutral">No</span>' ?></td>                        <td><?= (int) $s['include_financial_year'] === 1 ? '<span class="badge badge-soft-success">Yes</span>' : '<span class="badge badge-soft-neutral">No</span>' ?></td>                        <td class="num"><b><?= (int) $s['next_number'] ?></b></td>                        <td class="num text-muted"><?= (int) $s['last_used_number'] ?></td>                        <td class="num"><?= (int) $s['number_length'] ?></td>                        <td>                            <?php if ((int) $s['is_active'] === 1): ?>                                <span class="badge badge-soft-success">Active</span>                            <?php else: ?>                                <span class="badge badge-soft-danger">Inactive</span>                            <?php endif; ?>                        </td>                        <td class="actions-cell">                            <a href="<?= $this->url('/settings/numbering/' . (int) $s['id'] . '/edit') ?>" class="btn btn-sm btn-outline-primary btn-icon" title="Edit">                                <i class="bi bi-pencil"></i>                            </a>                            <button class="btn btn-sm btn-outline-warning btn-icon" title="Reset numbering"                                    data-bs-toggle="modal" data-bs-target="#resetModal"                                    data-id="<?= (int) $s['id'] ?>"                                    data-doc="<?= $this->e(str_replace('_', ' ', $s['document_type'])) ?>"                                    data-next="<?= (int) $s['next_number'] ?>"                                    data-last="<?= (int) $s['last_used_number'] ?>">                                <i class="bi bi-arrow-counterclockwise"></i>                            </button>                        </td>                    </tr>                <?php endforeach; ?>                </tbody>            </table>        </div>    </div></div><!-- Reset modal  confirmation, permission gate (server-side too), audit logged --><div class="modal fade" id="resetModal" tabindex="-1" aria-hidden="true">    <div class="modal-dialog">        <div class="modal-content">            <form method="post" action="" id="resetForm" data-confirm="Reset this numbering series? Historical documents keep their numbers, but verify the new next number is correct.">                <?= $this->csrfField() ?>                <div class="modal-header">                    <h5 class="modal-title"><i class="bi bi-arrow-counterclockwise me-1 text-warning"></i> Reset numbering</h5>                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>                </div>                <div class="modal-body">                    <div class="erp-alert erp-alert-warning mb-3">                        <i class="bi bi-exclamation-triangle"></i>                        <span><b>Warn:</b> resetting changes the next document number. The system will never allow a value that could duplicate an existing document number.</span>                    </div>                    <p class="small text-muted mb-2">Series: <b id="resetDocName"></b></p>                    <p class="small text-muted mb-2">Last number issued: <b id="resetLast"></b> &nbsp;&nbsp; Next number (currently): <b id="resetNext"></b></p>                    <label class="form-label" for="new_next_number">New next number</label>                    <input type="number" class="form-control" id="new_next_number" name="new_next_number" min="1" required>                    <div class="form-hint mt-1">This action is recorded in the audit trail with your user, date/time and IP.</div>                </div>                <div class="modal-footer">                    <button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button>                    <button type="submit" class="btn btn-warning"><i class="bi bi-arrow-counterclockwise"></i> Reset series</button>                </div>            </form>        </div>    </div></div><script>document.addEventListener('DOMContentLoaded', () => {    const modal = document.getElementById('resetModal');    if (!modal) return;    modal.addEventListener('show.bs.modal', (e) => {        const btn = e.relatedTarget;        document.getElementById('resetDocName').textContent = btn.dataset.doc;        document.getElementById('resetLast').textContent = btn.dataset.last;        document.getElementById('resetNext').textContent = btn.dataset.next;        document.getElementById('new_next_number').value = parseInt(btn.dataset.next, 10);        document.getElementById('resetForm').action = '/settings/numbering/' + btn.dataset.id + '/reset';    });});</script>